func PlFetch(p *planctx.Plan) int32 {
	// The ranges the host put in `cand` (`input offset length` triples) become the round's `bytes` requests `[6 4 -n input offset length]`, ids
	// -1, -2, ... for the whole unit. None is `need-bytes-stalled`: the unit missed and the source reports nothing missed.
	var n int32 = port.CellsLen(p.Cand)
	var i int32 = 0
	port.CellsDrop(p.Reqs, 0)
	port.CellsDrop(p.Got, 0)
	if n == 0 {
		p.Err = PeStalled()
		port.TextAscii(p.Msg, "the unit missed and the source reports nothing missed")
		return ActError()
	}
	for i < n {
		p.BytesRequests += 1
		var input int32 = port.CellsAt(p.Cand, i)
		var off int32 = port.CellsAt(p.Cand, i+1)
		var ln int32 = port.CellsAt(p.Cand, i+2)
		plan.RqBytes(p.Reqs, 0-p.BytesRequests, input, off, ln)
		i += 3
	}
	port.CellsDrop(p.Cand, 0)
	p.Outk = 1
	return ActFetch()
}

func PlOffer(p *planctx.Plan) int32 {
	// The answer in `cur` (a whole record) joins the round: refused (`act-error`, `bad-record`) when it is malformed, answers a request the round did
	// not make or whose kind it does not have, or answers one already answered. Answers 0 when taken.
	var n int32 = port.CellsLen(p.Cur)
	var declared int32 = 0
	if n > 0 {
		declared = port.CellsAt(p.Cur, 0)
	}
	if (n < 4) || (declared != n) {
		p.Err = PeBadRecord()
		port.TextAscii(p.Msg, "an answer has length ")
		port.TextI32(p.Msg, declared)
		port.TextAscii(p.Msg, " in a record of ")
		port.TextI32(p.Msg, n)
		return ActError()
	}
	var kind int32 = port.CellsAt(p.Cur, 1)
	var id int32 = port.CellsAt(p.Cur, 2)
	var at int32 = plan.RecFind(p.Reqs, id)
	if (at < 0) || ((port.CellsAt(p.Reqs, at+1) != kind) || (plan.RecFind(p.Got, id) >= 0)) {
		p.Err = PeBadRecord()
		port.TextAscii(p.Msg, "an answer for request ")
		port.TextI32(p.Msg, id)
		port.TextAscii(p.Msg, " (kind ")
		port.TextI32(p.Msg, kind)
		port.TextAscii(p.Msg, ") answers nothing asked")
		return ActError()
	}
	plCopy(p.Got, p.Cur, 0, n)
	return 0
}

func PlHas(p *planctx.Plan, id int32) int32 {
	// 1 when the round has been offered an answer to request `id`.
	if plan.RecFind(p.Got, id) >= 0 {
		return 1
	}
	return 0
}

func PlOwed(p *planctx.Plan) int32 {
	// How many requests of the round have no answer yet.
	var n int32 = port.CellsLen(p.Reqs)
	var at int32 = 0
	var k int32 = 0
	for at < n {
		if plan.RecFind(p.Got, port.CellsAt(p.Reqs, at+2)) < 0 {
			k += 1
		}
		at += port.CellsAt(p.Reqs, at)
	}
	return k
}

func PlCommit(p *planctx.Plan) int32 {
	// Every request of the round is answered. A `bytes` round: each answer must say ok (`fulfil-failed` otherwise), nothing is kept. A round of
	// requests: the answers join `ans` IN ID ORDER and the transcript's entries `[round request answer]` are written to `tx` in the same order.
	if PlOwed(p) != 0 {
		p.Err = PeBadRecord()
		port.TextAscii(p.Msg, "the round is not fully answered")
		return ActError()
	}
	var n int32 = port.CellsLen(p.Reqs)
	var at int32 = 0
	for at < n {
		var rl int32 = port.CellsAt(p.Reqs, at)
		var id int32 = port.CellsAt(p.Reqs, at+2)
		var ga int32 = plan.RecFind(p.Got, id)
		var al int32 = port.CellsAt(p.Got, ga)
		if p.Outk == 1 {
			if port.CellsAt(p.Got, ga+3) != plan.PsOk() {
				p.Err = PeFulfilFailed()
				p.ErrActual = port.CellsAt(p.Got, ga+3)
				port.TextAscii(p.Msg, "fetching bytes: status ")
				port.TextI32(p.Msg, port.CellsAt(p.Got, ga+3))
				return ActError()
			}
		} else {
			plCopy(p.Ans, p.Got, ga, al)
			port.CellsPush(p.Tx, p.Round)
			plCopy(p.Tx, p.Reqs, at, rl)
			plCopy(p.Tx, p.Got, ga, al)
		}
		at += rl
	}
	port.CellsDrop(p.Reqs, 0)
	port.CellsDrop(p.Got, 0)
	p.Outk = 0
	return 0
}

