func PlRoute(kind int32, ports int32) int32 {
	// Which port fulfils a request of `kind` (`rt-*`), given the ports configured (`pp-*`): a `decode` and a `decode-img` the host's own codecs; an `ocr`
	// the engine when there is one; a `render` or `crop` the renderer when there is one. With no port the answer is `unsupported` (D199), and a kind
	// no port may be asked for (`bytes` is the loop's own) is `rt-none`: the host's error.
	if kind == plan.PkDecode() {
		return RtDecode()
	}
	if kind == plan.PkDecodeImg() {
		return RtDecodeImg()
	}
	if kind == plan.PkOcr() {
		if (ports & PpOcr()) == PpOcr() {
			return RtOcr()
		}
		return RtUnsupported()
	}
	if (kind == plan.PkRender()) || (kind == plan.PkCrop()) {
		if (ports & PpRender()) == PpRender() {
			return RtRender()
		}
		return RtUnsupported()
	}
	return RtNone()
}

func PlUnsupported(out *port.Cells, kind int32, id int32) int32 {
	// The answer of a request no port is configured for.
	return plan.AnFail(out, kind, id, plan.PsUnsupported())
}

func PlSpans(c *port.Cells, at int32, me int32, out *port.Cells) int32 {
	// The spans of input `me` that the request at `at` names, as `offset length` pairs pushed to `out`: a `decode`'s, and a `decode-img`'s codestream and
	// globals when they are the input's own. A host that cannot block makes these resident before it answers. Answers how many.
	var kind int32 = plan.RecKind(c, at)
	var k int32 = 0
	if kind == plan.PkDecode() {
		if (plan.RqArg(c, at, 0) == me) && ((plan.RqArg(c, at, 1) >= 0) && (plan.RqArg(c, at, 2) > 0)) {
			port.CellsPush(out, plan.RqArg(c, at, 1))
			port.CellsPush(out, plan.RqArg(c, at, 2))
			k += 1
		}
	}
	if kind == plan.PkDecodeImg() {
		if (plan.RqArg(c, at, plan.DqWhere()) == me) && ((plan.RqArg(c, at, plan.DqOffset()) >= 0) && (plan.RqArg(c, at, plan.DqLength()) > 0)) {
			port.CellsPush(out, plan.RqArg(c, at, plan.DqOffset()))
			port.CellsPush(out, plan.RqArg(c, at, plan.DqLength()))
			k += 1
		}
		if (plan.RqArg(c, at, plan.DqGwhere()) == me) && ((plan.RqArg(c, at, plan.DqGoffset()) >= 0) && (plan.RqArg(c, at, plan.DqGlength()) > 0)) {
			port.CellsPush(out, plan.RqArg(c, at, plan.DqGoffset()))
			port.CellsPush(out, plan.RqArg(c, at, plan.DqGlength()))
			k += 1
		}
	}
	return k
}

func PlFold(p *planctx.Plan) int32 {
	// The unit that just finished (`phase`) adds its accounting to the totals, and the unit is reset. The document pass and the asset unit count
	// attempts, fetch rounds, bytes requests and requests; a page unit counts its requests and keeps its rounds and requests; the figures unit
	// its requests.
	var ph int32 = p.Phase
	if (ph == PhDoc()) || (ph == PhAsset()) {
		p.TAttempts += p.Attempts
		p.TFetchRounds += p.FetchRounds
		p.TBytesRequests += p.BytesRequests
	}
	if ph == PhPages() {
		port.CellsPush(p.Pgr, p.Rounds)
		port.CellsPush(p.Pgq, p.Requests)
	}
	if ph != PhFinish() {
		p.TRequests += p.Requests
	}
	PlReset(p)
	return 0
}

func EnNext(p *planctx.Plan, kind int32, assets int32, pending int32, np int32) int32 {
	// THE SCHEDULE (P10.6 S4): the unit that follows the one `phase` names, which is set and answered (`ph-*`). `kind` is what the document pass built:
	// 0 nothing (an intake), 1 a PDF, 2 a raster input. `assets` is whether the level is on, `pending` whether the document unit left the figures unit
	// to run (D351), `np` the page count. The document pass is followed by the asset unit (a PDF with assets on) or the page units; a document of no
	// pages goes straight to its document unit.
	var ph int32 = p.Phase
	if ph == PhDoc() {
		if kind == 0 {
			p.Phase = PhDone()
			return PhDone()
		}
		if (kind == 1) && (assets != 0) {
			p.Phase = PhAsset()
			return PhAsset()
		}
		p.Phase = PhPages()
		p.Page = 0
		if np <= 0 {
			p.Phase = PhFinish()
		}
		return p.Phase
	}
	if ph == PhAsset() {
		p.Phase = PhPages()
		p.Page = 0
		if np <= 0 {
			p.Phase = PhFinish()
		}
		return p.Phase
	}
	if ph == PhPages() {
		p.Page += 1
		if p.Page >= np {
			p.Phase = PhFinish()
		}
		return p.Phase
	}
	if ph == PhFinish() {
		if pending != 0 {
			p.Phase = PhFigures()
		} else {
			p.Phase = PhDone()
		}
		return p.Phase
	}
	p.Phase = PhDone()
	return PhDone()
}

func fpHi(n int32, c int32, r int32) int32 {
	// The last chunk of the window around chunk `c`: c + r, or the last chunk of the input (c + r would leave 32 bits for a one-byte chunk of a 2 GiB input).
	if c > ((n - 1) - r) {
		return n - 1
	}
	return c + r
}

func fpEnd(n int32, last int32, chunk int32, ln int32) int32 {
	// Where the run ending at chunk `last` ends: the next chunk's start, or the input's length for the last chunk.
	if last == (n - 1) {
		return ln
	}
	return (last + 1) * chunk
}

func FpPlan(pend *port.Cells, hint *port.Cells, res *port.Cells, chunk int32, ln int32, input int32, round int32, out *port.Cells) int32 {
	// The ranges to fetch for fetch round `round` (0, 1, ...), as `input offset length` triples pushed to `out`; answers how many. `pend` and `hint` are
	// the chunks the source missed and the chunks it was asked to expect, each in ascending order; `res` holds 1 for each resident chunk. Every seed
	// chunk and 2^round - 1 chunks each side of it (at most 2^20 - 1), the resident ones left out; a run of consecutive chunks is one range, the
	// last ending at `ln`. The input is `chunk` bytes to a chunk, `ln` bytes long.
	if (chunk <= 0) || (ln <= 0) {
		return 0
	}
	var n int32 = ((ln - 1) / chunk) + 1
	var r int32 = ((1) << uint(plMin(round, 20))) - 1
	var na int32 = port.CellsLen(pend)
	var nb int32 = port.CellsLen(hint)
	var ia int32 = 0
	var ib int32 = 0
	var cursor int32 = 0
	var open int32 = 0
	var first int32 = 0
	var last int32 = 0
	var k int32 = 0
	for (ia < na) || (ib < nb) {
		var c int32 = 0
		if (ia < na) && ((ib >= nb) || (port.CellsAt(pend, ia) <= port.CellsAt(hint, ib))) {
			c = port.CellsAt(pend, ia)
			ia += 1
		} else {
			c = port.CellsAt(hint, ib)
			ib += 1
		}
		if (c >= 0) && (c < n) {
			var hi int32 = fpHi(n, c, r)
			k = plMax(plMax(0, c-r), cursor)
			for k <= hi {
				if port.CellsAt(res, k) == 0 {
					if (open == 1) && (k == (last + 1)) {
						last = k
					} else {
						if open == 1 {
							port.CellsPush(out, input)
							port.CellsPush(out, first*chunk)
							port.CellsPush(out, fpEnd(n, last, chunk, ln)-(first*chunk))
						}
						open = 1
						first = k
						last = k
					}
				}
				k += 1
			}
			cursor = plMax(cursor, hi+1)
		}
	}
	if open == 1 {
		port.CellsPush(out, input)
		port.CellsPush(out, first*chunk)
		port.CellsPush(out, fpEnd(n, last, chunk, ln)-(first*chunk))
	}
	return port.CellsLen(out) / 3
}

func lbAt(m *port.Cells, n int32, at int32, k int32, a int32, b int32, d int32, e int32) int32 {
	// 1 when the first `k` of the four code points a b d e are at `at`.
	if (at + k) > n {
		return 0
	}
	if port.CellsAt(m, at) != a {
		return 0
	}
	if k > 1 {
		if port.CellsAt(m, at+1) != b {
			return 0
		}
	}
	if k > 2 {
		if port.CellsAt(m, at+2) != d {
			return 0
		}
	}
	if k > 3 {
		if port.CellsAt(m, at+3) != e {
			return 0
		}
	}
	return 1
}

func lbLimitIs(m *port.Cells, n int32, at int32) int32 {
	// 1 when " limit is " starts at `at`.
	if lbAt(m, n, at, 4, 32, 108, 105, 109) == 0 {
		return 0
	}
	if lbAt(m, n, at+4, 4, 105, 116, 32, 105) == 0 {
		return 0
	}
	return lbAt(m, n, at+8, 2, 115, 32, 0, 0)
}

func lbReached(m *port.Cells, n int32, at int32) int32 {
	// 1 when " and this input reached " starts at `at`.
	if lbAt(m, n, at, 4, 32, 97, 110, 100) == 0 {
		return 0
	}
	if lbAt(m, n, at+4, 4, 32, 116, 104, 105) == 0 {
		return 0
	}
	if lbAt(m, n, at+8, 4, 115, 32, 105, 110) == 0 {
		return 0
	}
	if lbAt(m, n, at+12, 4, 112, 117, 116, 32) == 0 {
		return 0
	}
	if lbAt(m, n, at+16, 4, 114, 101, 97, 99) == 0 {
		return 0
	}
	return lbAt(m, n, at+20, 4, 104, 101, 100, 32)
}

func lbNum(m *port.Cells, n int32, at int32) int32 {
	// The number written in digits at `at`, or -1 when there is none or it does not fit 31 bits.
	var i int32 = at
	var v int32 = 0
	for (i < n) && ((port.CellsAt(m, i) >= 48) && (port.CellsAt(m, i) <= 57)) {
		var dg int32 = port.CellsAt(m, i) - 48
		if (v > 214748364) || ((v == 214748364) && (dg > 7)) {
			return -1
		}
		v = (v * 10) + dg
		i += 1
	}
	if i == at {
		return -1
	}
	return v
}

func lbNumEnd(m *port.Cells, n int32, at int32) int32 {
	// Where the digits at `at` end.
	var i int32 = at
	for (i < n) && ((port.CellsAt(m, i) >= 48) && (port.CellsAt(m, i) <= 57)) {
		i += 1
	}
	return i
}

func LbParse(m *port.Cells, p *planctx.Plan) int32 {
	// `m` is a panic message as code points. When it is a limit breach: answers 1, with the limit's name in `p`'s `msg`, the limit in `err-limit` and
	// the number reached in `err-actual`; else 0, and nothing is written.
	var n int32 = port.CellsLen(m)
	var j int32 = 5
	var found int32 = -1
	if lbAt(m, n, 0, 4, 116, 104, 101, 32) == 0 {
		return 0
	}
	for (found < 0) && ((j + 10) <= n) {
		if lbLimitIs(m, n, j) == 1 {
			found = j
		}
		j += 1
	}
	if found < 0 {
		return 0
	}
	var ls int32 = found + 10
	var limit int32 = lbNum(m, n, ls)
	var le int32 = lbNumEnd(m, n, ls)
	if limit < 0 {
		return 0
	}
	if lbReached(m, n, le) == 0 {
		return 0
	}
	var actual int32 = lbNum(m, n, le+24)
	var i int32 = 4
	if actual < 0 {
		return 0
	}
	for i < found {
		var c int32 = port.CellsAt(m, i)
		if c == 32 {
			port.TextCp(p.Msg, 45)
		} else {
			port.TextCp(p.Msg, c)
		}
		i += 1
	}
	p.ErrLimit = limit
	p.ErrActual = actual
	return 1
}
